fn is_prime(n: i32) -> bool {
    if n < 2 { return false; }
    let mut d: i32 = 2;
    while d * d <= n {
        if n % d == 0 { return false; }
        d = d + 1;
    }
    true
}

fn frame(t: i32) {
    let h: i32 = host::display::height();
    host::display::clear(0x000000);
    let mut count: i32 = 0;
    let mut n: i32 = 2;
    while n < 100 {
        if is_prime(n) {
            count = count + 1;
            host::display::fill_rect(n * 5, h - 20, 2, 12, 0x00ff00);
        }
        n = n + 1;
    }
    host::display::draw_string(8, 10, "PRIMES UNDER 100", 0x808080, 1);
    host::display::draw_number(8, 26, count, 0xffffff, 3);
    host::display::present();
}
